use std::sync::{Arc, Mutex};
use std::thread;

// ---- Send and Sync traits ----
// Send: can be transferred between threads
// Sync: can be shared between threads

// ---- Arc: Atomic Reference Counted ----
// Arc is thread-safe version of Rc
fn main() {
    // ---- Basic Arc ----
    let data = Arc::new(vec![1, 2, 3, 4, 5]);

    let mut handles = vec![];
    for i in 0..5 {
        let data = Arc::clone(&data);
        let handle = thread::spawn(move || {
            println!("Thread {}: {:?}", i, data);
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    // ---- Arc with Mutex for mutable data ----
    let counter = Arc::new(Mutex::new(0));
    let mut handles2 = vec![];

    for _ in 0..10 {
        let counter = Arc::clone(&counter);
        let handle = thread::spawn(move || {
            let mut num = counter.lock().unwrap();
            *num += 1;
        });
        handles2.push(handle);
    }

    for handle in handles2 {
        handle.join().unwrap();
    }

    println!("Counter: {}", *counter.lock().unwrap());

    // ---- Send: types that can be sent to another thread ----
    // Most types implement Send automatically
    let data = String::from("Hello");
    let handle = thread::spawn(move || {
        println!("{}", data);
    });
    handle.join().unwrap();

    // ---- Sync: types that can be shared between threads ----
    // Most types implement Sync automatically
    let data = Arc::new(42);
    let mut handles3 = vec![];
    for _ in 0..3 {
        let data = Arc::clone(&data);
        let handle = thread::spawn(move || {
            println!("Shared data: {}", data);
        });
        handles3.push(handle);
    }
    for handle in handles3 {
        handle.join().unwrap();
    }

    // ---- Types that are not Send or Sync ----
    // Rc is not Send or Sync (not thread-safe)
    // RefCell is not Sync (not thread-safe)
    // Raw pointers are not Send or Sync

    // ---- Custom type with Send and Sync ----
    #[derive(Debug)]
    struct Player {
        name: String,
        health: i32,
    }

    // Player is Send and Sync (all fields are Send and Sync)
    let player = Arc::new(Player {
        name: String::from("Hero"),
        health: 100,
    });

    let mut handles4 = vec![];
    for _ in 0..3 {
        let player = Arc::clone(&player);
        let handle = thread::spawn(move || {
            println!("Player: {} (HP: {})", player.name, player.health);
        });
        handles4.push(handle);
    }
    for handle in handles4 {
        handle.join().unwrap();
    }
}

